DISPOSITIONS = {'npov_clause_489eec8f0bd4e224503b': {'meaning': 'The representation must be fair, proportionate, and without editorial bias as far as possible.', 'kind': 'RESULT_REQUIREMENT', 'reason': 'Fairness and neutrality describe the representation to achieve, not a prerequisite that the biased Before already satisfies.'}, 'npov_clause_78b1b320708606d1dc98': {'meaning': 'NPOV cannot be superseded by other policies, guidelines, or editor consensus.', 'kind': 'POLICY_AUTHORITY', 'reason': 'The non-supersession statement establishes policy authority, not a Before applicability requirement.'}, 'npov_clause_8f77533a4038e7289fcb': {'meaning': 'The opinion must be attributed to specific sources or described as widespread views.', 'kind': 'RESULT_REQUIREMENT', 'reason': 'Attribution is the prescribed result of editing an unattributed opinion; requiring it beforehand would suppress the edit.'}, 'npov_clause_6efef0e514d2b86e7964': {'meaning': 'The assertion must be treated as an opinion.', 'kind': 'RESULT_REQUIREMENT', 'reason': 'Opinion framing is the desired presentation after correction.'}, 'npov_clause_d6659fbbf9327bf46b7f': {'meaning': "The fact must be stated directly in Wikipedia's voice.", 'kind': 'RESULT_REQUIREMENT', 'reason': 'Direct factual voice is the prescribed result rather than a prerequisite.'}, 'npov_clause_adb83541be78a1b1f360': {'meaning': 'The language must be nonjudgmental and disinterested.', 'kind': 'RESULT_REQUIREMENT', 'reason': 'Nonjudgmental language is the desired result of neutralizing judgmental language.'}, 'npov_clause_45f42d24251ec01671f1': {'meaning': 'The reporting must reflect the relative levels of support for the views.', 'kind': 'RESULT_REQUIREMENT', 'reason': 'Relative prominence describes the target presentation; source operation remains unspecified where the rule has no action.'}, 'npov_clause_34924e90230b3f200e12': {'meaning': 'Rewriting is the preferred method for biased but fixable content.', 'kind': 'ACTION_GUIDANCE', 'reason': 'Preference for rewriting guides the operation; it does not require that an actual edit has already happened.'}, 'npov_clause_8c4561ed4ca70f23f0bb': {'meaning': 'Specific article structures are not prohibited as a rule, but must ensure broad neutrality.', 'kind': 'ACTION_GUIDANCE', 'reason': 'Source says structures are not prohibited as a class; its broad neutrality goal is not permission to gate edits on the measured POV segregation feature.'}, 'npov_clause_eacad7ac0530447a1921': {'meaning': "Tiny minority views should generally be excluded except in specific 'See also' contexts or articles devoted to them.", 'kind': 'UNRESOLVED_SCOPE', 'reason': 'The See-also/devoted-article exception needs source context; the existing undue-weight feature does not separately establish that exception. Applicability remains UNKNOWN when otherwise applicable.'}, 'npov_clause_975cb013995329621cdb': {'meaning': 'Do not present minority/fringe views as having equal validity to mainstream scholarship if it creates false balance.', 'kind': 'RESULT_REQUIREMENT', 'reason': 'Avoiding false balance is a target requirement, not a prerequisite that Before is already balanced.'}, 'npov_clause_67082d26d03fb27f6392': {'meaning': 'Spinoff sub-articles are permissible if written neutrally and not to evade consensus.', 'kind': 'UNRESOLVED_SCOPE', 'reason': 'Spinoff permission and consensus evasion require article-level context not established by a sentence neutrality feature. Applicability remains UNKNOWN when otherwise applicable.'}, 'npov_clause_80e01f2c5d3cd0c17005': {'meaning': 'The rule applies to article titles, not in-text references.', 'kind': 'REDUNDANT_SCOPE', 'reason': 'The retained condition explicitly says The text is an article title; the same title scope is already in the source applicability conjunction.'}, 'npov_clause_081037a4643eda0dc8a1': {'meaning': 'The title must not confine the content of the article to views on a particular side of an issue.', 'kind': 'RESULT_REQUIREMENT', 'reason': "The title's lack of one-sided framing is a target result."}, 'npov_clause_97023c5f907d804055c0': {'meaning': 'The title must not suggest a viewpoint for or against a topic.', 'kind': 'RESULT_REQUIREMENT', 'reason': "The title's lack of endorsement or rejection is a target result."}, 'npov_clause_8ea3f36b82d3b6d2960c': {'meaning': 'The tone must not endorse a particular point of view.', 'kind': 'RESULT_REQUIREMENT', 'reason': 'Not endorsing a viewpoint is the target tone rather than a prerequisite that the biased Before is already impartial.'}, 'npov_clause_d421b2a14d518ba5706c': {'meaning': 'The tone must not reject a particular point of view.', 'kind': 'RESULT_REQUIREMENT', 'reason': 'Not rejecting a viewpoint is the target tone; the existing negative-language feature must not be conjoined as a positive prerequisite.'}, 'npov_clause_d7299e3e980e9e8fd2ec': {'meaning': 'Direct quotes from participants in heated disputes should be avoided.', 'kind': 'ACTION_GUIDANCE', 'reason': 'Avoiding direct participant quotations guides wording; no separate Before gate is inferred.'}, 'npov_clause_088eb857930685b2e0b2': {'meaning': 'The replacement must consist of details that are actually factual.', 'kind': 'RESULT_REQUIREMENT', 'reason': 'Factual replacement details constrain the proposed result, not the current opinionated Before.'}}
